def f(g, keep=4):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=max(cnt,key=lambda x:(cnt[x],))
    # shape cells = minority cells
    shape=(x for x in cnt if x!=bg)
    from collections import deque
    vis=set()
    for r in range(H):
        for c in range(W):
            if (r,c) in shape or g[r][c]!=bg: continue
            if r in (0,H-1) or c in (0,W-1):
                dq=deque([(r,c)]); vis.add((r,c))
    while dq:
        p=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=p[0]+dr,p[1]+dc
            if 0<=q[0]<H and 0<=q[1]<W and g[q[0]][q[1]]==bg and q not in vis:
                vis.add(q); dq.append(q)
    return [[keep if (v not in vis and v!=bg) else g[v] for v in g[r]] for r in g]
