    for c in range(W):
        for r in [0,H-1]:
            if g[r][c]==bg and (r,c) not in vis: q.append((r,c)); vis.add((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and (nr,nc) not in vis and g[nr][nc]==bg:
